const job = await tools.job_output({ job_id: "pwsh-196" });
console.log("status:", job.job.status, "| output:", (job.text ?? "").slice(-300));
const fs = await import("node:fs");
const t = fs.readFileSync("C:/Users/jjq21/AppData/Local/Temp/ofm-subs-out.txt", "utf8");
console.log("FILE LEN:", t.length, "| DONE:", t.includes("DONE"));
// 提取几条关键正文
const blocks = t.split("--- ");
const want = [
  "now makes $14.2k monthly as a single developer",
  "Built 6 SaaS and got 0 customers",
  "I turned my gym membership into a mini call center",
  "From the corner of my 9-5 office",
];
for (const b of blocks) {
  for (const w of want) {
    if (b.includes(w)) {
      const title = b.slice(0, 110).split("\n")[0];
      console.log("\n========== " + title + " ==========");
      console.log(b.slice(0, 1200));
    }
  }
}
